parameters.jsCode:
// Selects the sources that are due to run.
//
// The whole due-source decision lives here, in n8n — the database stores
// next_run_at and priority but never acts on them.
//
// The sources table is small (dozens of rows), so it is fetched whole and
// filtered in memory rather than expressed as an OR query.

const all = $input.all().map(i => i.json);

// Settings rows and source rows arrive merged; separate them by shape.
const settingsRows = all.filter(r => typeof r.key === 'string' && 'value' in r);
const sources = all.filter(r => typeof r.base_url === 'string');

const setting = (key, fallback) => {
  const row = settingsRows.find(r => r.key === key);
  return row && row.value !== null && row.value !== undefined ? row.value : fallback;
};

// Non-critical setting: a missing interval map falls back to the documented
// defaults rather than halting ingestion.
const intervals = setting('ingestion.priority_intervals', {
  '1': 60, '2': 180, '3': 360, '4': 720, '5': 1440,
});

const now = Date.now();
const due = [];

for (const s of sources) {
  // Belt and braces: the DB constraint already forbids an active source that
  // is not verified, but never crawl on the strength of one check.
  if (!s.active || s.config_status !== 'verified') continue;
  if (s.parser_type === 'unknown') continue;

  // A source in retry backoff waits until its next_retry_at passes (M10).
  if (s.next_retry_at && new Date(s.next_retry_at).getTime() > now) continue;

  const intervalMinutes = s.poll_interval_minutes
    ?? Number(intervals[String(s.priority)] ?? 360);

  const nextRun = s.next_run_at ? new Date(s.next_run_at).getTime() : 0;
  if (nextRun > now) continue;

  due.push({
    json: {
      source: s,
      interval_minutes: intervalMinutes,
      trigger_type: 'scheduled',
      dispatched_at: new Date(now).toISOString(),
    },
  });
}

return due;

// RSS lane → RawItem[]
//
// parser_config may name which fields carry the date and body; both default
// to the RSS conventions. Nothing here is guessed at crawl time — an
// unconfigured source never reaches this workflow, because it cannot be
// activated.

const src = $('Called by scheduler').first().json.source;
const cfg = src.parser_config || {};
const dateField = cfg.date_field || 'pubDate';
const contentField = cfg.content_field || 'description';

const root = $input.first().json;
const channel = root?.rss?.channel ?? root?.feed ?? {};
let entries = channel.item ?? channel.entry ?? root?.feed?.entry ?? [];
if (!Array.isArray(entries)) entries = [entries];

const text = (v) => {
  if (v === null || v === undefined) return '';
  if (typeof v === 'string') return v;
  if (typeof v === 'object') return v._ ?? v['#text'] ?? '';
  return String(v);
};

const toIsoDate = (v) => {
  const raw = text(v);
  if (!raw) return null;
  const d = new Date(raw);
  // An unparseable date becomes null. The AI is instructed never to invent
  // one, and neither does this.
  return Number.isNaN(d.getTime()) ? null : d.toISOString().slice(0, 10);
};

const linkOf = (e) => {
  if (typeof e.link === 'string') return e.link;
  if (Array.isArray(e.link)) return e.link[0]?.$?.href ?? text(e.link[0]);
  return e.link?.$?.href ?? text(e.link) ?? e.guid ? text(e.guid) : '';
};

return entries.filter(Boolean).map((e) => ({
  json: {
    source_id: src.id,
    source_url: linkOf(e),
    title_raw: text(e.title),
    content_raw: text(e[contentField]) || text(e.summary) || text(e.content),
    publication_date: toIsoDate(e[dateField] ?? e.published ?? e.updated),
    attachments: [],
    fetched_at: new Date().toISOString(),
  },
}));

// API lane → RawItem[]
// Field paths come from parser_config, filled in by an admin who inspected
// the real response. Nothing is inferred.

const src = $('Called by scheduler').first().json.source;
const cfg = src.parser_config || {};

const dig = (obj, path) =>
  (path || '').split('.').filter(Boolean).reduce((o, k) => (o == null ? undefined : o[k]), obj);

const payload = $input.first().json;
let items = cfg.items_path ? dig(payload, cfg.items_path) : payload;
if (!Array.isArray(items)) items = items ? [items] : [];

const toIsoDate = (raw) => {
  if (!raw) return null;
  const d = new Date(raw);
  return Number.isNaN(d.getTime()) ? null : d.toISOString().slice(0, 10);
};

return items.map((it) => ({
  json: {
    source_id: src.id,
    source_url: String(dig(it, cfg.url) ?? ''),
    title_raw: String(dig(it, cfg.title) ?? ''),
    content_raw: String(dig(it, cfg.body) ?? ''),
    publication_date: toIsoDate(dig(it, cfg.date)),
    attachments: [],
    fetched_at: new Date().toISOString(),
  },
}));

// HTML lane → RawItem[]
//
// Selectors come from parser_config, which an admin filled in against the
// live page during verification. A source with an empty config cannot be
// marked verified and therefore cannot be active, so this never runs on
// guessed selectors.

const src = $('Called by scheduler').first().json.source;
const cfg = src.parser_config || {};
const base = new URL(src.base_url);

const blocks = $input.first().json.items || [];

// Minimal extraction over the fragment HTML. Kept dependency-free: the
// HTML node has already narrowed the document to the list items.
const pick = (html, selector) => {
  if (!selector) return '';
  const attrMatch = selector.match(/^(.*)@([\w-]+)$/);
  const sel = (attrMatch ? attrMatch[1] : selector).trim();
  const attr = attrMatch ? attrMatch[2] : null;
  const tag = sel.split(/[\s>]/).pop().replace(/[.#].*$/, '') || 'a';
  const re = new RegExp(`<${tag}[^>]*>([\\s\\S]*?)</${tag}>`, 'i');
  if (attr) {
    const attrRe = new RegExp(`<${tag}[^>]*\\s${attr}=["']([^"']+)["']`, 'i');
    const m = html.match(attrRe);
    return m ? m[1] : '';
  }
  const m = html.match(re);
  return m ? m[1].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim() : '';
};

const absolute = (href) => {
  if (!href) return '';
  try { return new URL(href, base).toString(); } catch { return ''; }
};

const toIsoDate = (raw) => {
  if (!raw) return null;
  const d = new Date(raw);
  return Number.isNaN(d.getTime()) ? null : d.toISOString().slice(0, 10);
};

return blocks.map((html) => {
  const link = absolute(pick(html, cfg.link));
  const pdfMatch = html.match(/href=["']([^"']+\.pdf)["']/i);
  return {
    json: {
      source_id: src.id,
      source_url: link,
      title_raw: pick(html, cfg.title),
      content_raw: pick(html, cfg.body),
      publication_date: toIsoDate(pick(html, cfg.date)),
      // PDF enrichment applies to every lane, not just parser_type = pdf:
      // gazettes routinely publish a listing entry whose substance is an
      // attached document.
      attachments: pdfMatch ? [absolute(pdfMatch[1])] : [],
      fetched_at: new Date().toISOString(),
    },
  };
});

// PDF-index lane → RawItem[]
//
// The page is a list of PDF links, typical of official gazettes. Each link
// becomes a RawItem carrying the document as an attachment; the download and
// text extraction happen in the enrichment step so every lane shares one
// implementation.

const src = $('Called by scheduler').first().json.source;
const cfg = src.parser_config || {};
const base = new URL(src.base_url);
const maxPages = Number(cfg.max_pages) || 40;

const html = typeof $input.first().json.data === 'string'
  ? $input.first().json.data
  : ($input.first().json.body ?? '');

const links = [...html.matchAll(/href=["']([^"']+\.pdf)["'][^>]*>([\s\S]*?)</gi)]
  .slice(0, maxPages)
  .map((m) => ({
    href: (() => { try { return new URL(m[1], base).toString(); } catch { return ''; } })(),
    label: m[2].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim(),
  }))
  .filter((l) => l.href);

return links.map((l) => ({
  json: {
    source_id: src.id,
    source_url: l.href,
    title_raw: l.label,
    content_raw: '',
    // The gazette listing rarely states a publication date; leave it null and
    // let the AI read it from the document rather than inventing one here.
    publication_date: null,
    attachments: [l.href],
    fetched_at: new Date().toISOString(),
  },
}));

// Normalises and validates every RawItem before anything downstream sees it.
//
// This is the single contract between parsing and the M9 AI stage: whatever
// lane produced an item, it leaves here in the same shape or not at all.

const src = $('Called by scheduler').first().json.source;
const allowed = (src.allowed_domains || []).map((d) => String(d).toLowerCase());

const out = [];
const rejected = { no_url: 0, no_title: 0, domain_mismatch: 0 };

for (const item of $input.all()) {
  const r = item.json;

  if (!r.source_url) { rejected.no_url += 1; continue; }
  if (!r.title_raw || !String(r.title_raw).trim()) { rejected.no_title += 1; continue; }

  // Domain check happens here as well as in the Publishing Gate (M9). An item
  // whose URL is off the source's allow-list is not worth spending an AI call
  // on, and it must never be attributed to this authority.
  let host;
  try { host = new URL(r.source_url).hostname.toLowerCase(); } catch { rejected.no_url += 1; continue; }
  if (!allowed.includes(host)) { rejected.domain_mismatch += 1; continue; }

  out.push({
    json: {
      source_id: src.id,
      source_url: r.source_url,
      title_raw: String(r.title_raw).trim().slice(0, 2000),
      content_raw: String(r.content_raw || '').trim().slice(0, 50000),
      publication_date: r.publication_date || null,
      attachments: Array.isArray(r.attachments) ? r.attachments.slice(0, 5) : [],
      fetched_at: r.fetched_at || new Date().toISOString(),
      // carried through so M9 can log against the right source
      source: {
        id: src.id,
        country: src.country,
        authority_ar: src.authority_ar,
        allowed_domains: src.allowed_domains,
      },
    },
  });
}

console.log(`normalised ${out.length} items; rejected ${JSON.stringify(rejected)}`);

// M9 attaches the AI stage and the Publishing Gate to this output.
return out;

// Fetch failure for this source.
//
// Isolated on purpose: one unreachable source must not stop the others in the
// same scheduler tick. M10 turns this into retry state and a health snapshot;
// for now it records the failure and ends this source's run.

const src = $('Called by scheduler').first().json.source;
const err = $input.first().json.error || $input.first().json;

return [{
  json: {
    failed: true,
    source_id: src.id,
    authority_ar: src.authority_ar,
    error_message: String(err?.message || err?.reason || 'fetch failed').slice(0, 1000),
  },
}];

