parameters.jsCode:
// Carries the RawItem alongside the AI response so the validator can pair
// them. n8n keeps item order through the HTTP node, but pairing explicitly is
// cheaper than relying on that.
const items = $('Normalise RawItem').all().map(i => i.json);
return $input.all().map((entry, i) => ({ json: { ...entry.json, __item: items[i] } }));

// Parses and validates the model's JSON. FAIL CLOSED.
//
// Anything malformed, incomplete, or outside the allowed enums is rejected
// outright — never coerced, never defaulted. A coerced category would put a
// confident wrong classification in a legal archive, which is worse than a gap.

const COUNTRY = ['SA','AE','KW','QA','BH','OM','GCC'];
const CATEGORY = ['tax','customs','employment','corporate','financial','capital_markets','banking','data_privacy','cybersecurity','competition','intellectual_property','litigation','licensing','real_estate','energy','healthcare','trade','general'];
const DOC_TYPE = ['law','royal_decree','ministerial_decision','executive_regulation','circular','regulatory_framework','official_notice','court_precedent','consultation_draft','other'];
const STATUS = ['enacted','effective','draft','amended','repealed','pending'];

const ISO_DATE = /^\d{4}-\d{2}-\d{2}$/;
const isDate = (v) => {
  if (v === null || v === undefined || v === '') return true;
  if (typeof v !== 'string' || !ISO_DATE.test(v)) return false;
  const d = new Date(v + 'T00:00:00Z');
  return !Number.isNaN(d.getTime()) && d.toISOString().slice(0,10) === v;
};
const strList = (v) => Array.isArray(v) && v.every(x => typeof x === 'string');
const nonEmpty = (v) => typeof v === 'string' && v.trim().length > 0;

const out = [];

for (const entry of $input.all()) {
  const item = entry.json.__item;
  const response = entry.json;

  const fail = (reason, detail) => out.push({ json: {
    __item: item, __rejected: true, reason, detail: detail ? String(detail).slice(0,300) : null,
  }});

  // The Messages API returns content blocks; the text block carries the JSON.
  const text = response?.content?.[0]?.text;
  if (!nonEmpty(text)) { fail('ai_empty_response'); continue; }

  let ai;
  try {
    ai = JSON.parse(text.trim());
  } catch {
    // One tolerated shape: the model wrapped the object in prose or a fence.
    const m = text.match(/\{[\s\S]*\}/);
    if (!m) { fail('ai_parse_failure', text); continue; }
    try { ai = JSON.parse(m[0]); } catch { fail('ai_parse_failure', text); continue; }
  }

  if (!ai || typeof ai !== 'object' || Array.isArray(ai)) { fail('ai_not_an_object'); continue; }

  if (!nonEmpty(ai.title_ar)) { fail('ai_invalid_output', 'title_ar'); continue; }
  if (!nonEmpty(ai.summary_ar)) { fail('ai_invalid_output', 'summary_ar'); continue; }
  if (!COUNTRY.includes(ai.country)) { fail('ai_invalid_output', 'country=' + ai.country); continue; }
  if (!CATEGORY.includes(ai.category)) { fail('ai_invalid_output', 'category=' + ai.category); continue; }
  if (!DOC_TYPE.includes(ai.document_type)) { fail('ai_invalid_output', 'document_type=' + ai.document_type); continue; }
  if (!STATUS.includes(ai.legal_status)) { fail('ai_invalid_output', 'legal_status=' + ai.legal_status); continue; }
  if (typeof ai.is_legal_update !== 'boolean') { fail('ai_invalid_output', 'is_legal_update'); continue; }
  if (typeof ai.confidence !== 'number' || !Number.isFinite(ai.confidence) || ai.confidence < 0 || ai.confidence > 1) {
    fail('ai_invalid_output', 'confidence=' + ai.confidence); continue;
  }
  if (!isDate(ai.effective_date)) { fail('ai_invalid_output', 'effective_date=' + ai.effective_date); continue; }
  if (!isDate(ai.publication_date)) { fail('ai_invalid_output', 'publication_date=' + ai.publication_date); continue; }
  if (ai.affected_entities !== undefined && !strList(ai.affected_entities)) { fail('ai_invalid_output', 'affected_entities'); continue; }
  if (ai.keywords !== undefined && !strList(ai.keywords)) { fail('ai_invalid_output', 'keywords'); continue; }

  out.push({ json: {
    __item: item,
    __rejected: false,
    ai: {
      title_ar: ai.title_ar.trim(),
      summary_ar: ai.summary_ar.trim(),
      country: ai.country,
      category: ai.category,
      document_type: ai.document_type,
      legal_status: ai.legal_status,
      is_legal_update: ai.is_legal_update,
      confidence: ai.confidence,
      publication_date: ai.publication_date || null,
      effective_date: ai.effective_date || null,
      affected_entities: (ai.affected_entities || []).slice(0, 20),
      keywords: (ai.keywords || []).slice(0, 20),
    },
  }});
}

return out;

// Builds the string that becomes content_hash, and drops items the AI stage
// already rejected.
//
// Hash inputs: source_id | source_url | title | publication_date. The URL is
// included deliberately — two authorities republishing the same instrument at
// different URLs are two archive entries, and the M3 exclusion-group rule
// handles the mirror case instead.

const out = [];
for (const entry of $input.all()) {
  const e = entry.json;
  if (e.__rejected) { out.push({ json: e }); continue; }

  const item = e.__item;
  const pubDate = item.publication_date || e.ai.publication_date || '';

  out.push({ json: {
    ...e,
    hash_input: [item.source_id, item.source_url, e.ai.title_ar, pubDate].join('|'),
  }});
}
return out;

// Prepares the Publishing Gate payload and reads the fail-closed threshold.
//
// ai.confidence_threshold is deliberately NOT defaulted here. If it is missing
// or malformed the gate rejects everything — defaulting it could quietly widen
// what publishes, so absence must be loud.

const settings = $('Get threshold').all().map(i => i.json);
const row = settings.find(r => r.key === 'ai.confidence_threshold');
const threshold = row && typeof row.value === 'number' ? row.value : null;

const out = [];
for (const entry of $input.all()) {
  const e = entry.json;
  if (e.__rejected) { out.push({ json: e }); continue; }

  const item = e.__item;
  out.push({ json: {
    __rejected: false,
    confidence_threshold: threshold,
    ai: e.ai,
    item: {
      source_id: item.source_id,
      source_url: item.source_url,
      content_hash: e.content_hash,
      publication_date: item.publication_date,
      // Verbatim source text, stored so a lawyer can check the summary against
      // what the authority actually published.
      raw_excerpt: (item.content_raw || item.title_raw || '').slice(0, 20000),
      // The official document URL, preserved end to end.
      document_path: (item.attachments && item.attachments[0]) || null,
      ai_model: 'claude-sonnet-5',
    },
  }});
}
return out;

// Aggregates every outcome for this source into ONE workflow_logs row.
//
// One row per source per run, not one per item: workflow_logs records
// executions, and the dashboard aggregates from it. Rejections are counted in
// rejection_reasons rather than logged individually — a rejection is a normal
// decision, not an incident.

const src = $('Called by scheduler').first().json.source;
const started = $('Called by scheduler').first().json.dispatched_at || new Date().toISOString();
const trigger = $('Called by scheduler').first().json.trigger_type || 'scheduled';

let fetched = 0, published = 0, rejected = 0;
const reasons = {};
let errorMessage = null;

for (const entry of $input.all()) {
  const e = entry.json;
  fetched += 1;

  if (e.__rejected) {
    rejected += 1;
    reasons[e.reason] = (reasons[e.reason] || 0) + 1;
    continue;
  }
  if (e.outcome === 'published') { published += 1; continue; }
  if (e.outcome === 'duplicate') { rejected += 1; reasons.duplicate = (reasons.duplicate || 0) + 1; continue; }
  if (e.outcome === 'rejected') {
    rejected += 1;
    reasons[e.reason || 'unknown'] = (reasons[e.reason || 'unknown'] || 0) + 1;
    continue;
  }
  if (e.outcome === 'insert_failed') {
    rejected += 1;
    reasons.insert_failed = (reasons.insert_failed || 0) + 1;
    errorMessage = e.error_message || errorMessage;
  }
}

const finished = new Date().toISOString();

// partial: some items failed to insert. failed is reserved for a run that
// could not fetch at all, which the M10 failure branch records.
const status = errorMessage ? 'partial' : 'success';

return [{ json: {
  workflow_name: '02-source-ingestion',
  execution_id: String($execution.id),
  source_id: src.id,
  trigger_type: trigger,
  status,
  items_fetched: fetched,
  items_published: published,
  items_rejected: rejected,
  rejection_reasons: reasons,
  error_message: errorMessage,
  duration_ms: Math.max(0, new Date(finished).getTime() - new Date(started).getTime()),
  retry_attempt: 0,
  started_at: started,
  finished_at: finished,
}}];

// THE PUBLISHING GATE — the five rules, in one place.
//
// This sub-workflow is the ONLY code that decides whether something enters the
// archive. Scheduled ingestion, manual runs (M10) and any future backfill all
// call it, so the rules cannot drift between callers.
//
// The database enforces none of this. It stores what it is given and rejects
// only what is structurally impossible (a duplicate hash, a confidence outside
// 0..1). Every judgement below is n8n's.

const input = $('Called by scheduler').first().json;
const item = input.item;
const ai = input.ai;
const threshold = input.confidence_threshold;

const sourceRows = $('Re-read source').all().map(i => i.json).filter(r => r && r.id);
const hashRows = $('Look up hash').all().map(i => i.json).filter(r => r && r.id);

const reject = (reason, detail) => [{
  json: { published: false, reason, detail: detail ?? null, source_id: item.source_id, content_hash: item.content_hash },
}];

// ── Rule 0: the threshold itself must be present and sane ──────────────────
// ai.confidence_threshold is a FAIL-CLOSED setting. If it is missing or
// malformed the gate rejects everything rather than assuming a value, because
// assuming one could quietly widen what publishes.
if (typeof threshold !== 'number' || !Number.isFinite(threshold) || threshold < 0 || threshold > 1) {
  return reject('missing_confidence_threshold', String(threshold));
}

// ── Rule 1: the source is registered, active and verified ──────────────────
// Re-read at publish time, not trusted from the crawl: an admin may have
// deactivated or un-verified the source while this item was in flight.
const source = sourceRows[0];
if (!source) return reject('unknown_source');
if (!source.active) return reject('inactive_source', source.authority_ar);
if (source.config_status !== 'verified') return reject('unverified_source', source.config_status);

// ── Rule 2: the item's URL is on the source's allow-list ───────────────────
let host;
try {
  const u = new URL(item.source_url);
  if (u.protocol !== 'https:' && u.protocol !== 'http:') return reject('bad_url_scheme', u.protocol);
  host = u.hostname.toLowerCase();
} catch {
  return reject('malformed_url', item.source_url);
}
const allowed = (source.allowed_domains || []).map(d => String(d).toLowerCase());
if (!allowed.includes(host)) return reject('domain_mismatch', host);

// ── Rule 3: not already published ──────────────────────────────────────────
// The UNIQUE constraint is the backstop for the concurrent race; this is the
// ordinary path, and a duplicate is a skip, never an error.
if (hashRows.length > 0) return reject('duplicate', item.content_hash);

// ── Rule 4: confidence clears the threshold ────────────────────────────────
if (typeof ai.confidence !== 'number' || ai.confidence < threshold) {
  return reject('low_confidence', String(ai.confidence));
}

// ── Rule 5: it is actually a legal update ──────────────────────────────────
if (ai.is_legal_update !== true) return reject('not_legal_update');

// ── Publication date: taken, never invented ────────────────────────────────
// The crawler's date wins; the AI's is used only when the crawler found none.
// If neither exists the item is rejected rather than stamped with the fetch
// time, which would put a fabricated legal date in the archive.
const publicationDate = item.publication_date || ai.publication_date || null;
if (!publicationDate) return reject('no_publication_date');

// ── Country: the registry is authoritative ─────────────────────────────────
// The source's country is used unless the AI identified a GCC-wide instrument,
// which legitimately appears on national sites.
const country = ai.country === 'GCC' ? 'GCC' : source.country;

return [{
  json: {
    published: true,
    row: {
      source_id: source.id,
      content_hash: item.content_hash,
      source_url: item.source_url,
      title_ar: ai.title_ar,
      summary_ar: ai.summary_ar,
      country,
      category: ai.category,
      document_type: ai.document_type,
      legal_status: ai.legal_status,
      is_legal_update: true,
      confidence: ai.confidence,
      effective_date: ai.effective_date || null,
      publication_date: publicationDate,
      affected_entities: ai.affected_entities || [],
      keywords: ai.keywords || [],
      raw_excerpt: item.raw_excerpt,
      document_path: item.document_path || null,
      ai_model: item.ai_model,
    },
  },
}];

// Insert succeeded.
const row = $('Apply the five rules').first().json.row;
return [{ json: { outcome: 'published', source_id: row.source_id, content_hash: row.content_hash } }];

// Insert failed.
//
// A unique-violation here is the concurrent-execution race the constraint
// exists for: two runs classified the same item at once and both passed the
// gate's hash lookup. That is a DUPLICATE, not a failure — classifying it as
// an error would make a healthy source look broken.

const gate = $('Apply the five rules').first().json;
const err = $input.first().json.error ?? $input.first().json;
const message = String(err?.message ?? err?.details ?? err ?? 'insert failed');

const isDuplicate = /duplicate key|content_hash_unique|23505/i.test(message);

return [{
  json: {
    outcome: isDuplicate ? 'duplicate' : 'insert_failed',
    source_id: gate.row?.source_id ?? null,
    content_hash: gate.row?.content_hash ?? null,
    error_message: isDuplicate ? null : message.slice(0, 1000),
  },
}];

// Rejected by the gate. Not an error — a decision, carried back to the caller
// so it can be counted in workflow_logs.rejection_reasons.
const g = $input.first().json;
return [{ json: { outcome: 'rejected', reason: g.reason, detail: g.detail, source_id: g.source_id } }];

// Retry taxonomy — mirrors lib/ops/retry.ts, which is the tested specification.
const RETRYABLE = new Set(['network_timeout','dns_failure','connection_reset','http_408','http_429','http_500','http_502','http_503','http_504','db_connection_failure','ai_provider_unavailable','ai_rate_limited','storage_unavailable']);

const isRetryable = (code) => RETRYABLE.has(code);

const codeForHttpStatus = (s) => {
  if (s === 408) return 'http_408';
  if (s === 429) return 'http_429';
  if ([500,502,503,504].includes(s)) return 'http_' + s;
  if (s >= 500) return 'http_500';
  if (s === 401) return 'http_401';
  if (s === 403) return 'http_403';
  if (s === 404) return 'http_404';
  if (s === 410) return 'http_410';
  if (s >= 400) return 'http_400';
  return 'ok';
};

// Exponential backoff WITH JITTER. Without jitter a batch of sources that
// failed together would retry in lockstep forever, keeping the herd
// synchronised on whatever upstream knocked them over.
const backoffMs = (attempt, schedule) => {
  const s = (schedule && schedule.length) ? schedule : [5,15,45,120,360];
  const base = (s[Math.min(Math.max(attempt,1), s.length) - 1] || 5) * 60000;
  const spread = base * 0.2;
  return Math.max(1000, Math.round(base + (Math.random() * 2 - 1) * spread));
};

// ── RETRY SWEEP ────────────────────────────────────────────────────────────
// Runs every 15 minutes. Finds sources whose backoff has elapsed and decides,
// per source, whether another attempt is warranted or the job is dead.
//
// Idempotent: it only ever moves a source forward — either scheduling the next
// attempt or marking it dead. It never re-enqueues an item already published,
// because the Publishing Gate's hash check runs on every path.

const all = $input.all().map(i => i.json);
const settings = all.filter(r => typeof r.key === 'string');
const sources  = all.filter(r => typeof r.base_url === 'string');

const setting = (key, fallback) => {
  const row = settings.find(r => r.key === key);
  return row && row.value !== null && row.value !== undefined ? row.value : fallback;
};

const schedule = setting('ingestion.retry_backoff_minutes', [5,15,45,120,360]);
const maxAttempts = Array.isArray(schedule) ? schedule.length : 5;
const now = Date.now();

const toRetry = [];
const toKill = [];

for (const s of sources) {
  if (!s.active || s.config_status !== 'verified') continue;
  if (s.retry_attempt <= 0) continue;
  if (!s.next_retry_at || new Date(s.next_retry_at).getTime() > now) continue;

  const code = s.last_error_code || 'unknown_error';

  // A permanent error is not retried at all, however many attempts remain.
  // Retrying a 404 or a selector mismatch cannot succeed and only delays the
  // moment somebody notices.
  if (!isRetryable(code)) {
    toKill.push({ json: { source: s, reason: 'permanent_error', error_code: code } });
    continue;
  }

  if (s.retry_attempt >= maxAttempts) {
    toKill.push({ json: { source: s, reason: 'max_attempts_exhausted', error_code: code } });
    continue;
  }

  const next = s.retry_attempt + 1;
  toRetry.push({ json: {
    source: s,
    trigger_type: 'retry',
    dispatched_at: new Date().toISOString(),
    attempt_number: next,
    max_attempts: maxAttempts,
    next_backoff_ms: backoffMs(next, schedule),
  }});
}

console.log(JSON.stringify({ stage: 'retry_sweep', retrying: toRetry.length, dead: toKill.length }));
return [...toRetry, ...toKill];

// ── DEAD LETTER ────────────────────────────────────────────────────────────
// Builds the dead-letter row for a job that will not be retried again.
//
// The payload is written WITHOUT credentials: parser_config.headers can carry
// an API key for an authenticated feed, so it is stripped here. A CHECK
// constraint on the table rejects credential-shaped keys as a backstop.

const out = [];
for (const entry of $input.all()) {
  const e = entry.json;
  if (!e.reason) continue;               // this branch only handles deaths
  const s = e.source;

  const cfg = { ...(s.parser_config || {}) };
  delete cfg.headers;                    // never persist auth headers
  delete cfg.authorization;
  delete cfg.api_key;

  out.push({ json: {
    source_id: s.id,
    stage: 'fetch',
    item_url: s.feed_url || s.base_url,
    content_hash: null,
    error_code: e.error_code,
    error_message: (s.last_failure_reason || '').slice(0, 1000) || null,
    attempt_number: s.retry_attempt || 0,
    max_attempts: 5,
    first_attempt_at: s.first_attempt_at || null,
    last_attempt_at: s.last_failure_at || new Date().toISOString(),
    workflow_execution_id: String($execution.id),
    payload: { authority_ar: s.authority_ar, base_url: s.base_url, parser_type: s.parser_type, parser_config: cfg },
    state: 'open',
  }});
}
return out;

// ── HEALTH SNAPSHOT ────────────────────────────────────────────────────────
// Mirrors lib/ops/health.ts, which is the tested specification.
//
// Health measures whether the platform can RETRIEVE AND PROCESS a source.
// Duplicates, gate rejections on the merits, and empty runs NEVER reduce the
// score — a ministry that published nothing this week is quiet, not broken,
// and a dashboard that says otherwise trains people to ignore it.

const all = $input.all().map(i => i.json);
const settings = all.filter(r => typeof r.key === 'string');
const sources  = all.filter(r => typeof r.base_url === 'string');
const logs     = all.filter(r => typeof r.workflow_name === 'string');
const deads    = all.filter(r => typeof r.error_code === 'string' && r.state === 'open');

const setting = (key, fb) => {
  const row = settings.find(r => r.key === key);
  return row && row.value !== null && row.value !== undefined ? row.value : fb;
};

const failThreshold = Number(setting('ingestion.failure_alert_threshold', 5));
const defaultSilence = Number(setting('health.stale_after_minutes', 1440));
const cooldownMinutes = 180;
const now = Date.now();
const ratio = (n, d) => (d <= 0 ? null : Math.min(1, Math.max(0, n / d)));

const snapshots = [];
const alerts = [];

for (const s of sources) {
  const runs = logs.filter(l => l.source_id === s.id);
  const deadCount = deads.filter(d => d.source_id === s.id).length;

  let fetchOk = 0, extractionOk = 0, gateAttempts = 0, gateAccepted = 0, dupes = 0, durationTotal = 0;
  let aiAttempts = 0, aiOk = 0, lastItemFoundAt = null;

  for (const l of runs) {
    durationTotal += l.duration_ms || 0;
    if (l.status !== 'failed') fetchOk += 1;
    if ((l.items_fetched || 0) > 0) extractionOk += 1;

    const reasons = l.rejection_reasons || {};
    const aiFailures = (reasons.ai_parse_failure || 0) + (reasons.ai_invalid_output || 0);
    const items = (l.items_published || 0) + (l.items_rejected || 0);
    aiAttempts += items;
    aiOk += Math.max(0, items - aiFailures);

    gateAttempts += items;
    gateAccepted += l.items_published || 0;
    dupes += reasons.duplicate || 0;

    if ((l.items_published || 0) > 0 && (!lastItemFoundAt || l.started_at > lastItemFoundAt)) {
      lastItemFoundAt = l.started_at;
    }
  }

  const rates = {
    fetch: ratio(fetchOk, runs.length),
    extraction: ratio(extractionOk, fetchOk),
    ai: ratio(aiOk, aiAttempts),
    gate: ratio(gateAccepted, gateAttempts),
    dupe: ratio(dupes, gateAttempts),
  };

  const neverChecked = !s.last_run_at;
  const everSucceeded = !!s.last_success_at;
  const silence = s.max_silence_minutes || defaultSilence;

  // Staleness is measured from the last SUCCESSFUL CHECK, not the last item —
  // a source polled successfully that simply has nothing to say is healthy.
  const stale = everSucceeded && (now - new Date(s.last_success_at).getTime()) > silence * 60000;

  let score = 100;
  score -= Math.min(60, (s.consecutive_failures || 0) * 15);
  if (rates.fetch !== null) score -= (1 - rates.fetch) * 30;
  if (rates.extraction !== null) score -= (1 - rates.extraction) * 20;
  if (rates.ai !== null) score -= (1 - rates.ai) * 15;
  if (stale) score -= 20;
  if (deadCount > 0) score -= Math.min(15, deadCount * 5);
  score = Math.max(0, Math.min(100, Math.round(score)));

  let classification;
  if (!s.active) classification = 'disabled';
  else if (s.config_status !== 'verified') classification = 'unverified';
  else if (neverChecked) classification = 'never_run';
  else if ((s.consecutive_failures || 0) >= failThreshold || score < 40) classification = 'failing';
  else if ((s.consecutive_failures || 0) > 0 || score < 70) classification = 'degraded';
  else if (stale) classification = 'stale';
  else classification = 'healthy';

  snapshots.push({ json: {
    __kind: 'snapshot',
    source_id: s.id,
    classification,
    health_score: score,
    enabled: !!s.active,
    verified: s.config_status === 'verified',
    stale,
    last_checked_at: s.last_run_at,
    last_success_at: s.last_success_at,
    last_item_found_at: lastItemFoundAt,
    consecutive_failures: s.consecutive_failures || 0,
    dead_job_count: deadCount,
    window_runs: runs.length,
    fetch_success_rate: rates.fetch,
    extraction_success_rate: rates.extraction,
    ai_success_rate: rates.ai,
    gate_acceptance_rate: rates.gate,
    duplicate_rate: rates.dupe,
    avg_response_ms: runs.length ? Math.round(durationTotal / runs.length) : null,
    last_http_status: s.last_http_status || null,
    last_error_code: s.last_error_code || null,
    last_error_message: s.last_failure_reason || null,
  }});

  // ── alerting ────────────────────────────────────────────────────────────
  const previous = s.health_status;
  let kind = null;
  if (classification === 'failing' && previous !== 'failing') kind = 'source.failing';
  else if (classification === 'degraded' && previous !== 'degraded' && previous !== 'failing') kind = 'source.degraded';
  else if (classification === 'healthy' && (previous === 'degraded' || previous === 'failing')) kind = 'source.recovered';

  if (kind) {
    // Cooldown suppresses repeats of the SAME alert, so a flapping source does
    // not page anyone every fifteen minutes. Recovery is never suppressed —
    // leaving someone believing a source is still broken is worse than noise.
    const withinCooldown = kind !== 'source.recovered'
      && s.last_alert_at
      && s.last_alert_kind === kind
      && (now - new Date(s.last_alert_at).getTime()) < cooldownMinutes * 60000;

    if (!withinCooldown) {
      alerts.push({ json: {
        __kind: 'alert',
        event: kind,
        source_id: s.id,
        authority_ar: s.authority_ar,
        classification,
        previous,
        health_score: score,
        consecutive_failures: s.consecutive_failures || 0,
      }});
    }
  }
}

console.log(JSON.stringify({ stage: 'health_snapshot', snapshots: snapshots.length, alerts: alerts.length }));
return [...snapshots, ...alerts];

// Roll the classification, score and alert cooldown onto the source row so
// the dashboard and the next cooldown check read current state.
const snap = $input.first().json;
return [{ json: {
  id: snap.source_id,
  health_status: snap.classification,
  health_score: snap.health_score,
}}];

// Alert payload for the outbound signed event.
//
// Nothing sensitive: source identity, classification and counts only. No
// credentials, no headers, no raw payloads.
return $input.all().map(e => ({ json: {
  event: e.json.event,
  source_id: e.json.source_id,
  authority_ar: e.json.authority_ar,
  classification: e.json.classification,
  previous: e.json.previous,
  health_score: e.json.health_score,
  consecutive_failures: e.json.consecutive_failures,
  emitted_at: new Date().toISOString(),
}}));

// ── MANUAL RUN RESOLVER ────────────────────────────────────────────────────
// Verifies the signed request and resolves the requested scope to a source set.
//
// The resolved sources go into the SAME ingestion workflow the scheduler uses.
// There is no simplified manual path: a second pipeline would be a second set
// of rules to keep in step, and the one used in an emergency is the one least
// likely to be right.

const body = $('Manual run webhook').first().json.body || {};
const headers = $('Manual run webhook').first().json.headers || {};

const all = $input.all().map(i => i.json).filter(r => typeof r.base_url === 'string');
const scope = body.scope;
const now = Date.now();

let selected = [];
if (scope === 'source') selected = all.filter(s => s.id === body.source_id);
else if (scope === 'country') selected = all.filter(s => s.country === body.country);
else if (scope === 'all' || scope === 'drain') selected = all;
else if (scope === 'url' || scope === 'replay') {
  selected = body.source_id ? all.filter(s => s.id === body.source_id) : all;
}

// Only what the scheduler would run anyway. A manual run cannot activate a
// source the database refuses to activate.
selected = selected.filter(s => s.active && s.config_status === 'verified' && s.parser_type !== 'unknown');

const runnable = [];
const skipped = [];

for (const s of selected) {
  const locked = s.lock_expires_at && new Date(s.lock_expires_at).getTime() > now;
  if (locked && !body.force) {
    skipped.push({ json: { skipped: true, reason: 'already_running', source_id: s.id, authority_ar: s.authority_ar } });
    continue;
  }
  runnable.push({ json: {
    source: s,
    trigger_type: 'manual',
    dispatched_at: new Date().toISOString(),
    correlation_id: body.correlation_id || null,
    requested_by: body.requested_by || null,
    single_url: scope === 'url' ? body.url : null,
    dead_letter_id: scope === 'replay' ? body.dead_letter_id : null,
    forced: !!body.force,
  }});
}

console.log(JSON.stringify({
  stage: 'manual_run', correlation_id: body.correlation_id,
  scope, runnable: runnable.length, skipped: skipped.length,
}));

return [...runnable, ...skipped];

// Manual run outcome, returned to the caller and logged.
const results = $input.all().map(i => i.json);
const processed = results.length;
const inserted = results.reduce((a, r) => a + (r.items_published || 0), 0);
const rejected = results.reduce((a, r) => a + (r.items_rejected || 0), 0);
const failed = results.filter(r => r.status === 'failed').length;
const duplicates = results.reduce((a, r) => a + ((r.rejection_reasons || {}).duplicate || 0), 0);

return [{ json: {
  event: failed > 0 ? 'manual_run.failed' : 'manual_run.completed',
  execution_id: String($execution.id),
  processed, inserted, duplicates, rejected, failed,
  finished_at: new Date().toISOString(),
}}];

// A source already running is reported as skipped, not as an error — it is a
// normal outcome of the double-submission guard.
return $input.all().map(e => ({ json: { ...e.json, event: 'manual_run.skipped' } }));

// Selects the sources that are due to run.
//
// The whole due-source decision lives here, in n8n — the database stores
// next_run_at and priority but never acts on them.
//
// The sources table is small (dozens of rows), so it is fetched whole and
// filtered in memory rather than expressed as an OR query.

const all = $input.all().map(i => i.json);

// Settings rows and source rows arrive merged; separate them by shape.
const settingsRows = all.filter(r => typeof r.key === 'string' && 'value' in r);
const sources = all.filter(r => typeof r.base_url === 'string');

const setting = (key, fallback) => {
  const row = settingsRows.find(r => r.key === key);
  return row && row.value !== null && row.value !== undefined ? row.value : fallback;
};

// Non-critical setting: a missing interval map falls back to the documented
// defaults rather than halting ingestion.
const intervals = setting('ingestion.priority_intervals', {
  '1': 60, '2': 180, '3': 360, '4': 720, '5': 1440,
});

const now = Date.now();
const due = [];

for (const s of sources) {
  // Belt and braces: the DB constraint already forbids an active source that
  // is not verified, but never crawl on the strength of one check.
  if (!s.active || s.config_status !== 'verified') continue;
  if (s.parser_type === 'unknown') continue;

  // A source in retry backoff waits until its next_retry_at passes (M10).
  if (s.next_retry_at && new Date(s.next_retry_at).getTime() > now) continue;

  const intervalMinutes = s.poll_interval_minutes
    ?? Number(intervals[String(s.priority)] ?? 360);

  const nextRun = s.next_run_at ? new Date(s.next_run_at).getTime() : 0;
  if (nextRun > now) continue;

  due.push({
    json: {
      source: s,
      interval_minutes: intervalMinutes,
      trigger_type: 'scheduled',
      dispatched_at: new Date(now).toISOString(),
    },
  });
}

return due;

// RSS lane → RawItem[]
//
// parser_config may name which fields carry the date and body; both default
// to the RSS conventions. Nothing here is guessed at crawl time — an
// unconfigured source never reaches this workflow, because it cannot be
// activated.

const src = $('Called by scheduler').first().json.source;
const cfg = src.parser_config || {};
const dateField = cfg.date_field || 'pubDate';
const contentField = cfg.content_field || 'description';

const root = $input.first().json;
const channel = root?.rss?.channel ?? root?.feed ?? {};
let entries = channel.item ?? channel.entry ?? root?.feed?.entry ?? [];
if (!Array.isArray(entries)) entries = [entries];

const text = (v) => {
  if (v === null || v === undefined) return '';
  if (typeof v === 'string') return v;
  if (typeof v === 'object') return v._ ?? v['#text'] ?? '';
  return String(v);
};

const toIsoDate = (v) => {
  const raw = text(v);
  if (!raw) return null;
  const d = new Date(raw);
  // An unparseable date becomes null. The AI is instructed never to invent
  // one, and neither does this.
  return Number.isNaN(d.getTime()) ? null : d.toISOString().slice(0, 10);
};

const linkOf = (e) => {
  if (typeof e.link === 'string') return e.link;
  if (Array.isArray(e.link)) return e.link[0]?.$?.href ?? text(e.link[0]);
  return e.link?.$?.href ?? text(e.link) ?? e.guid ? text(e.guid) : '';
};

return entries.filter(Boolean).map((e) => ({
  json: {
    source_id: src.id,
    source_url: linkOf(e),
    title_raw: text(e.title),
    content_raw: text(e[contentField]) || text(e.summary) || text(e.content),
    publication_date: toIsoDate(e[dateField] ?? e.published ?? e.updated),
    attachments: [],
    fetched_at: new Date().toISOString(),
  },
}));

// API lane → RawItem[]
// Field paths come from parser_config, filled in by an admin who inspected
// the real response. Nothing is inferred.

const src = $('Called by scheduler').first().json.source;
const cfg = src.parser_config || {};

const dig = (obj, path) =>
  (path || '').split('.').filter(Boolean).reduce((o, k) => (o == null ? undefined : o[k]), obj);

const payload = $input.first().json;
let items = cfg.items_path ? dig(payload, cfg.items_path) : payload;
if (!Array.isArray(items)) items = items ? [items] : [];

const toIsoDate = (raw) => {
  if (!raw) return null;
  const d = new Date(raw);
  return Number.isNaN(d.getTime()) ? null : d.toISOString().slice(0, 10);
};

return items.map((it) => ({
  json: {
    source_id: src.id,
    source_url: String(dig(it, cfg.url) ?? ''),
    title_raw: String(dig(it, cfg.title) ?? ''),
    content_raw: String(dig(it, cfg.body) ?? ''),
    publication_date: toIsoDate(dig(it, cfg.date)),
    attachments: [],
    fetched_at: new Date().toISOString(),
  },
}));

// HTML lane → RawItem[]
//
// Selectors come from parser_config, which an admin filled in against the
// live page during verification. A source with an empty config cannot be
// marked verified and therefore cannot be active, so this never runs on
// guessed selectors.

const src = $('Called by scheduler').first().json.source;
const cfg = src.parser_config || {};
const base = new URL(src.base_url);

const blocks = $input.first().json.items || [];

// Minimal extraction over the fragment HTML. Kept dependency-free: the
// HTML node has already narrowed the document to the list items.
const pick = (html, selector) => {
  if (!selector) return '';
  const attrMatch = selector.match(/^(.*)@([\w-]+)$/);
  const sel = (attrMatch ? attrMatch[1] : selector).trim();
  const attr = attrMatch ? attrMatch[2] : null;
  const tag = sel.split(/[\s>]/).pop().replace(/[.#].*$/, '') || 'a';
  const re = new RegExp(`<${tag}[^>]*>([\\s\\S]*?)</${tag}>`, 'i');
  if (attr) {
    const attrRe = new RegExp(`<${tag}[^>]*\\s${attr}=["']([^"']+)["']`, 'i');
    const m = html.match(attrRe);
    return m ? m[1] : '';
  }
  const m = html.match(re);
  return m ? m[1].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim() : '';
};

const absolute = (href) => {
  if (!href) return '';
  try { return new URL(href, base).toString(); } catch { return ''; }
};

const toIsoDate = (raw) => {
  if (!raw) return null;
  const d = new Date(raw);
  return Number.isNaN(d.getTime()) ? null : d.toISOString().slice(0, 10);
};

return blocks.map((html) => {
  const link = absolute(pick(html, cfg.link));
  const pdfMatch = html.match(/href=["']([^"']+\.pdf)["']/i);
  return {
    json: {
      source_id: src.id,
      source_url: link,
      title_raw: pick(html, cfg.title),
      content_raw: pick(html, cfg.body),
      publication_date: toIsoDate(pick(html, cfg.date)),
      // PDF enrichment applies to every lane, not just parser_type = pdf:
      // gazettes routinely publish a listing entry whose substance is an
      // attached document.
      attachments: pdfMatch ? [absolute(pdfMatch[1])] : [],
      fetched_at: new Date().toISOString(),
    },
  };
});

// PDF-index lane → RawItem[]
//
// The page is a list of PDF links, typical of official gazettes. Each link
// becomes a RawItem carrying the document as an attachment; the download and
// text extraction happen in the enrichment step so every lane shares one
// implementation.

const src = $('Called by scheduler').first().json.source;
const cfg = src.parser_config || {};
const base = new URL(src.base_url);
const maxPages = Number(cfg.max_pages) || 40;

const html = typeof $input.first().json.data === 'string'
  ? $input.first().json.data
  : ($input.first().json.body ?? '');

const links = [...html.matchAll(/href=["']([^"']+\.pdf)["'][^>]*>([\s\S]*?)</gi)]
  .slice(0, maxPages)
  .map((m) => ({
    href: (() => { try { return new URL(m[1], base).toString(); } catch { return ''; } })(),
    label: m[2].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim(),
  }))
  .filter((l) => l.href);

return links.map((l) => ({
  json: {
    source_id: src.id,
    source_url: l.href,
    title_raw: l.label,
    content_raw: '',
    // The gazette listing rarely states a publication date; leave it null and
    // let the AI read it from the document rather than inventing one here.
    publication_date: null,
    attachments: [l.href],
    fetched_at: new Date().toISOString(),
  },
}));

// Normalises and validates every RawItem before anything downstream sees it.
//
// This is the single contract between parsing and the M9 AI stage: whatever
// lane produced an item, it leaves here in the same shape or not at all.

const src = $('Called by scheduler').first().json.source;
const allowed = (src.allowed_domains || []).map((d) => String(d).toLowerCase());

const out = [];
const rejected = { no_url: 0, no_title: 0, domain_mismatch: 0 };

for (const item of $input.all()) {
  const r = item.json;

  if (!r.source_url) { rejected.no_url += 1; continue; }
  if (!r.title_raw || !String(r.title_raw).trim()) { rejected.no_title += 1; continue; }

  // Domain check happens here as well as in the Publishing Gate (M9). An item
  // whose URL is off the source's allow-list is not worth spending an AI call
  // on, and it must never be attributed to this authority.
  let host;
  try { host = new URL(r.source_url).hostname.toLowerCase(); } catch { rejected.no_url += 1; continue; }
  if (!allowed.includes(host)) { rejected.domain_mismatch += 1; continue; }

  out.push({
    json: {
      source_id: src.id,
      source_url: r.source_url,
      title_raw: String(r.title_raw).trim().slice(0, 2000),
      content_raw: String(r.content_raw || '').trim().slice(0, 50000),
      publication_date: r.publication_date || null,
      attachments: Array.isArray(r.attachments) ? r.attachments.slice(0, 5) : [],
      fetched_at: r.fetched_at || new Date().toISOString(),
      // carried through so M9 can log against the right source
      source: {
        id: src.id,
        country: src.country,
        authority_ar: src.authority_ar,
        allowed_domains: src.allowed_domains,
      },
    },
  });
}

console.log(`normalised ${out.length} items; rejected ${JSON.stringify(rejected)}`);

// M9 attaches the AI stage and the Publishing Gate to this output.
return out;

// Fetch failure for this source.
//
// Isolated on purpose: one unreachable source must not stop the others in the
// same scheduler tick. M10 turns this into retry state and a health snapshot;
// for now it records the failure and ends this source's run.

const src = $('Called by scheduler').first().json.source;
const err = $input.first().json.error || $input.first().json;

return [{
  json: {
    failed: true,
    source_id: src.id,
    authority_ar: src.authority_ar,
    error_message: String(err?.message || err?.reason || 'fetch failed').slice(0, 1000),
  },
}];

